insert into public.modules (id, title, description, position) values ('mod-1', 'Boas-vindas e método', 'Como a mentoria funciona, o cronograma das 12 semanas e como tirar o máximo dos encontros ao vivo.', 0) on conflict (id) do nothing;
insert into public.lessons (id, module_id, title, description, duration_min, video_url, materials, position) values ('aula-1', 'mod-1', 'Como a mentoria está organizada', 'Visão geral dos módulos, do grupo de alunos e dos encontros quinzenais de discussão de casos.', 12, 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', '[{"id":"mat-guia","name":"Guia da mentoria (PDF)","url":"/materiais/guia-da-mentoria.pdf"}]'::jsonb, 0) on conflict (id) do nothing;
insert into public.lessons (id, module_id, title, description, duration_min, video_url, materials, position) values ('aula-2', 'mod-1', 'Montando sua rotina de estudo', 'Um plano semanal realista para quem atende em consultório: quando assistir, quando praticar, quando revisar.', 9, 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/friday.mp4', '[]'::jsonb, 1) on conflict (id) do nothing;
insert into public.lessons (id, module_id, title, description, duration_min, video_url, materials, position) values ('aula-3', 'mod-1', 'Documentação fotográfica dos seus casos', 'Padrão de fotos e radiografias que vamos usar para discutir casos durante a mentoria.', 18, 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', '[]'::jsonb, 2) on conflict (id) do nothing;
insert into public.modules (id, title, description, position) values ('mod-2', 'Diagnóstico e planejamento', 'Testes de sensibilidade, leitura de radiografia e tomografia, e como decidir entre tratar, retratar ou encaminhar.', 1) on conflict (id) do nothing;
insert into public.lessons (id, module_id, title, description, duration_min, video_url, materials, position) values ('aula-4', 'mod-2', 'Anamnese e testes de sensibilidade', 'Testes térmicos, elétricos, percussão e palpação: o que cada um responde e como registrar.', 22, 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/friday.mp4', '[]'::jsonb, 0) on conflict (id) do nothing;
insert into public.lessons (id, module_id, title, description, duration_min, video_url, materials, position) values ('aula-5', 'mod-2', 'Leitura radiográfica periapical', 'Sistemática para ler a periapical sem pular etapas, com 10 casos comentados.', 26, 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', '[]'::jsonb, 1) on conflict (id) do nothing;
insert into public.lessons (id, module_id, title, description, duration_min, video_url, materials, position) values ('aula-6', 'mod-2', 'Quando pedir tomografia', 'Indicações reais de CBCT em endodontia e como ler os cortes que importam.', 19, 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/friday.mp4', '[]'::jsonb, 2) on conflict (id) do nothing;
insert into public.lessons (id, module_id, title, description, duration_min, video_url, materials, position) values ('aula-7', 'mod-2', 'Plano de tratamento e prognóstico', 'Como apresentar o plano ao paciente e documentar o prognóstico de forma clara.', 24, 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', '[]'::jsonb, 3) on conflict (id) do nothing;
insert into public.modules (id, title, description, position) values ('mod-3', 'Acesso e localização de canais', 'Cavidade de acesso conservadora, anatomia interna por grupo dental e a busca pelo MB2.', 2) on conflict (id) do nothing;
insert into public.lessons (id, module_id, title, description, duration_min, video_url, materials, position) values ('aula-8', 'mod-3', 'Anatomia interna por grupo dental', 'Número de canais, curvaturas e variações mais frequentes em cada grupo dental.', 28, 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/friday.mp4', '[]'::jsonb, 0) on conflict (id) do nothing;
insert into public.lessons (id, module_id, title, description, duration_min, video_url, materials, position) values ('aula-9', 'mod-3', 'Cavidade de acesso conservadora', 'Desgaste mínimo com acesso em linha reta: brocas, sequência e erros comuns.', 21, 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', '[]'::jsonb, 1) on conflict (id) do nothing;
insert into public.lessons (id, module_id, title, description, duration_min, video_url, materials, position) values ('aula-10', 'mod-3', 'Localizando o MB2', 'Magnificação, ultrassom e o mapa do assoalho da câmara pulpar para não deixar o MB2 para trás.', 17, 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/friday.mp4', '[]'::jsonb, 2) on conflict (id) do nothing;
insert into public.lessons (id, module_id, title, description, duration_min, video_url, materials, position) values ('aula-11', 'mod-3', 'Odontometria eletrônica', 'Uso do localizador apical, confirmação radiográfica e registro do comprimento de trabalho.', 15, 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', '[]'::jsonb, 3) on conflict (id) do nothing;
insert into public.modules (id, title, description, position) values ('mod-4', 'Instrumentação mecanizada', 'Sistemas rotatórios e reciprocantes, glide path e como instrumentar canais curvos com segurança.', 3) on conflict (id) do nothing;
insert into public.lessons (id, module_id, title, description, duration_min, video_url, materials, position) values ('aula-12', 'mod-4', 'Glide path manual e mecanizado', 'Por que o glide path vem antes de tudo e como fazer em canais atresiados.', 16, 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/friday.mp4', '[]'::jsonb, 0) on conflict (id) do nothing;
insert into public.lessons (id, module_id, title, description, duration_min, video_url, materials, position) values ('aula-13', 'mod-4', 'Sistemas rotatórios', 'Cinemática, torque e velocidade: configurando o motor para cada sistema.', 27, 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', '[]'::jsonb, 1) on conflict (id) do nothing;
insert into public.lessons (id, module_id, title, description, duration_min, video_url, materials, position) values ('aula-14', 'mod-4', 'Sistemas reciprocantes', 'Lima única reciprocante passo a passo, com indicações e limites.', 23, 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/friday.mp4', '[]'::jsonb, 2) on conflict (id) do nothing;
insert into public.lessons (id, module_id, title, description, duration_min, video_url, materials, position) values ('aula-15', 'mod-4', 'Prevenindo fratura de instrumento', 'Fadiga cíclica, torção e o protocolo de descarte que evita acidentes.', 20, 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', '[]'::jsonb, 3) on conflict (id) do nothing;
