insert into public.lessons (id, module_id, title, description, duration_min, video_url, materials, position) values ('aula-18', 'mod-5', 'Protocolo final de irrigação', 'A sequência completa que usamos na clínica, pronta para imprimir.', 12, 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/friday.mp4', '[{"id":"mat-irrigacao","name":"Protocolo de irrigação (PDF)","url":"/materiais/protocolo-de-irrigacao.pdf"}]'::jsonb, 2) on conflict (id) do nothing;
