insert into public.notes (user_id, lesson_id, body) values ('00000000-0000-4000-a000-000000000001', 'aula-6', 'Pedir CBCT quando houver suspeita de reabsorção ou canal extra que a periapical não resolve.') on conflict do nothing;
insert into public.notes (user_id, lesson_id, body) values ('00000000-0000-4000-a000-000000000001', 'aula-9', 'Ultrassom E1 para remover a dentina do assoalho antes de procurar o MB2.') on conflict do nothing;
insert into public.threads (id, title, body, author_id, module_id, lesson_id, created_at) values ('duv-1', 'Quando parar de procurar o MB2?', 'Num primeiro molar superior, removi a dentina do assoalho com ultrassom, usei magnificação e mesmo assim não encontrei o MB2. Até onde vale insistir antes de obturar só com três canais? Fico com medo de desgastar demais.', '00000000-0000-4000-a000-000000000001', 'mod-3', 'aula-10', '2026-11-18T14:55:54.007Z') on conflict (id) do nothing;
insert into public.threads (id, title, body, author_id, module_id, lesson_id, created_at) values ('duv-2', 'Glide path manual antes da reciprocante em curvatura abrupta?', 'Em canais com curvatura abrupta no terço apical, vocês sempre fazem glide path manual antes da lima reciprocante ou dá para ir direto com a lima de glide mecanizada?', '00000000-0000-4000-a000-000000000003', 'mod-4', 'aula-14', '2026-11-19T12:55:54.007Z') on conflict (id) do nothing;
insert into public.threads (id, title, body, author_id, module_id, lesson_id, created_at) values ('duv-3', 'Localizador apical instável em dente com polpa vital', 'A leitura do localizador fica pulando quando o canal tem polpa vital e sangramento. Já sequei com cone de papel, mas continua instável. Alguma dica?', '00000000-0000-4000-a000-000000000004', 'mod-3', 'aula-11', '2026-11-20T11:55:54.007Z') on conflict (id) do nothing;
insert into public.threads (id, title, body, author_id, module_id, lesson_id, created_at) values ('duv-4', 'Hipoclorito a 2,5% ou 5,25% no dia a dia?', 'Na clínica eu uso 2,5% por costume. Vale a pena mudar a concentração ou o que pesa mais é volume e agitação?', '00000000-0000-4000-a000-000000000005', 'mod-5', 'aula-16', '2026-11-16T18:55:54.007Z') on conflict (id) do nothing;
insert into public.threads (id, title, body, author_id, module_id, lesson_id, created_at) values ('duv-5', 'Qual periapical usar para documentar os casos da mentoria?', 'Para os casos que vamos discutir nos encontros, a radiografia digital do consultório serve ou precisa de algum padrão específico de posicionador?', '00000000-0000-4000-a000-000000000006', 'mod-1', 'aula-3', '2026-11-20T15:55:54.007Z') on conflict (id) do nothing;
insert into public.threads (id, title, body, author_id, module_id, lesson_id, created_at) values ('duv-6', 'Pedir tomografia antes de todo retratamento?', 'Nos retratamentos que chegam no consultório, vocês pedem CBCT sempre ou só em situações específicas?', '00000000-0000-4000-a000-000000000001', 'mod-2', 'aula-6', '2026-11-14T22:55:54.007Z') on conflict (id) do nothing;
insert into public.replies (id, thread_id, author_id, body, created_at) values ('res-1', 'duv-1', '00000000-0000-4000-a000-000000000002', 'Ótima pergunta. Siga a linha do sulco entre o MV e o palatino, removendo dentina com ultrassom em passos curtos e checando sempre na magnificação. Se depois de 1 a 2 mm de busca orientada ainda não aparecer nada, pare: o desgaste extra enfraquece o dente. Documente, obture os canais encontrados e, se houver sintomas persistentes, a tomografia ajuda a decidir. Vamos ver um caso assim no próximo encontro.', '2026-11-18T18:55:54.007Z') on conflict (id) do nothing;
insert into public.replies (id, thread_id, author_id, body, created_at) values ('res-2', 'duv-1', '00000000-0000-4000-a000-000000000003', 'Complementando: corar o assoalho com azul de metileno me ajudou a enxergar a linha do sulco.', '2026-11-19T02:55:54.007Z') on conflict (id) do nothing;
insert into public.replies (id, thread_id, author_id, body, created_at) values ('res-3', 'duv-2', '00000000-0000-4000-a000-000000000002', 'Em curvatura abrupta, comece com lima manual fina para sentir a anatomia e confirmar a patência. Com o caminho livre e reproduzível, a lima de glide mecanizada fica segura. O que não vale é levar a reciprocante a um canal sem caminho confirmado.', '2026-11-19T16:55:54.007Z') on conflict (id) do nothing;
insert into public.replies (id, thread_id, author_id, body, created_at) values ('res-4', 'duv-4', '00000000-0000-4000-a000-000000000003', 'Eu uso 2,5% e renovo bastante a solução. Tenho tido bons resultados.', '2026-11-17T00:55:54.007Z') on conflict (id) do nothing;
insert into public.replies (id, thread_id, author_id, body, created_at) values ('res-5', 'duv-4', '00000000-0000-4000-a000-000000000002', 'Concentração ajuda, mas volume, renovação frequente e agitação pesam tanto quanto. Com 2,5% bem renovado e agitado você está em um protocolo consistente. O protocolo completo está no PDF da aula de irrigação final.', '2026-11-17T05:55:54.007Z') on conflict (id) do nothing;
insert into public.replies (id, thread_id, author_id, body, created_at) values ('res-6', 'duv-6', '00000000-0000-4000-a000-000000000002', 'Não em todos. Peça quando a periapical não responde à pergunta clínica: suspeita de canal não tratado, reabsorção, perfuração ou lesão que não bate com a imagem 2D. A aula de tomografia traz os critérios que usamos.', '2026-11-15T08:55:54.007Z') on conflict (id) do nothing;
insert into public.thread_votes (thread_id, user_id) values ('duv-1', '00000000-0000-4000-a000-000000000004') on conflict do nothing;
insert into public.thread_votes (thread_id, user_id) values ('duv-1', '00000000-0000-4000-a000-000000000005') on conflict do nothing;
